Layer.InitColorCommand:
%
			function(self)
				if ThisGameCommand:GetText() == 'Game Start' then
					self.GainFocusColor = { 0.5,1.0,0.5,1 }
					self.LoseFocusColor = { 0.3,0.6,0.3,1 }
				elseif ThisGameCommand:GetText() == 'Exit' then
					self.GainFocusColor = { 1.0,1.0,0.5,1 }
					self.LoseFocusColor = { 0.6,0.6,0.3,1 }
				else
					self.GainFocusColor = { 1.0,0.3,0.3,1 }
					self.LoseFocusColor = { 0.6,0.2,0.2,1 }
				end
			end

%
			function(self)
				if ThisGameCommand:GetText() == 'Game Start' then
					self.GainFocusColor = { 1.0,1.0,0.0,1 }
					self:diffuse( 0.5,0.6,0.4,1 )
				elseif ThisGameCommand:GetText() == 'Exit' then
					self.GainFocusColor = { 1.0,0.4,0.0,1 }
					self:diffuse( 0.6,0.1,0.0,1 )
				else
					self.GainFocusColor = { 1.0,0.8,0.0,1 }
					self:diffuse( 0.55,0.5,0.5,1 )
				end
			end
